#include <vector>
#include <algorithm>
#include <unordered_map>

using namespace std;

class Solution {
    int maxLength = 0;
    int minNodes = 1;
    vector<vector<pair<int, int>>> graph;
    vector<int> prefix;
    unordered_map<int, int> lastSeen;

    void dfs(int u, int prev, vector<int> leftBoundary, const vector<int>& nums) {
        int val = nums[u];
        int prevDepth = lastSeen.count(val) ? lastSeen[val] : 0;
        lastSeen[val] = (int)prefix.size();

        if (prevDepth != 0) {
            leftBoundary.push_back(prevDepth);
            sort(leftBoundary.begin(), leftBoundary.end());
            leftBoundary = {leftBoundary[leftBoundary.size() - 2], leftBoundary.back()};
        }

        int startIdx = leftBoundary[0];
        int length = prefix.back() - prefix[startIdx];
        int nodes = (int)prefix.size() - startIdx;

        if (length > maxLength) {
            maxLength = length;
            minNodes = nodes;
        } else if (length == maxLength) {
            minNodes = min(minNodes, nodes);
        }

        for (const auto& edge : graph[u]) {
            int v = edge.first;
            int w = edge.second;
            if (v != prev) {
                prefix.push_back(prefix.back() + w);
                dfs(v, u, leftBoundary, nums);
                prefix.pop_back();
            }
        }

        lastSeen[val] = prevDepth;
    }

public:
    vector<int> longestSpecialPath(vector<vector<int>>& edges, vector<int>& nums) {
        int n = nums.size();
        graph.assign(n, vector<pair<int, int>>());
        for (const auto& e : edges) {
            graph[e[0]].emplace_back(e[1], e[2]);
            graph[e[1]].emplace_back(e[0], e[2]);
        }

        maxLength = 0;
        minNodes = 1;
        prefix = {0};
        lastSeen.clear();

        dfs(0, -1, {0, 0}, nums);
        return {maxLength, minNodes};
    }
};

import java.util.*;

class Solution {
    private int maxLength = 0;
    private int minNodes = 1;
    private List<List<int[]>> graph;
    private List<Integer> prefix;
    private Map<Integer, Integer> lastSeen;

    private void dfs(int u, int prev, int[] leftBoundary, int[] nums) {
        int val = nums[u];
        int prevDepth = lastSeen.getOrDefault(val, 0);
        lastSeen.put(val, prefix.size());

        int[] nextBoundary = leftBoundary;
        if (prevDepth != 0) {
            int[] cand = new int[]{leftBoundary[0], leftBoundary[1], prevDepth};
            Arrays.sort(cand);
            nextBoundary = new int[]{cand[1], cand[2]};
        }

        int startIdx = nextBoundary[0];
        int length = prefix.get(prefix.size() - 1) - prefix.get(startIdx);
        int nodes = prefix.size() - startIdx;

        if (length > maxLength) {
            maxLength = length;
            minNodes = nodes;
        } else if (length == maxLength) {
            minNodes = Math.min(minNodes, nodes);
        }

        for (int[] edge : graph.get(u)) {
            int v = edge[0];
            int w = edge[1];
            if (v != prev) {
                prefix.add(prefix.get(prefix.size() - 1) + w);
                dfs(v, u, nextBoundary, nums);
                prefix.remove(prefix.size() - 1);
            }
        }

        lastSeen.put(val, prevDepth);
    }

    public int[] longestSpecialPath(int[][] edges, int[] nums) {
        int n = nums.length;
        graph = new ArrayList<>();
        for (int i = 0; i < n; i++) graph.add(new ArrayList<>());
        for (int[] e : edges) {
            graph.get(e[0]).add(new int[]{e[1], e[2]});
            graph.get(e[1]).add(new int[]{e[0], e[2]});
        }

        maxLength = 0;
        minNodes = 1;
        prefix = new ArrayList<>();
        prefix.add(0);
        lastSeen = new HashMap<>();

        dfs(0, -1, new int[]{0, 0}, nums);
        return new int[]{maxLength, minNodes};
    }
}

var longestSpecialPath = function(edges, nums) {
    const n = nums.length;
    const graph = Array.from({ length: n }, () => []);
    for (const [u, v, w] of edges) {
        graph[u].push([v, w]);
        graph[v].push([u, w]);
    }

    let maxLength = 0;
    let minNodes = 1;
    const prefix = [0];
    const lastSeen = new Map();

    function dfs(u, prev, leftBoundary) {
        const val = nums[u];
        const prevDepth = lastSeen.has(val) ? lastSeen.get(val) : 0;
        lastSeen.set(val, prefix.length);

        let nextBoundary = leftBoundary;
        if (prevDepth !== 0) {
            const arr = [leftBoundary[0], leftBoundary[1], prevDepth];
            arr.sort((a, b) => a - b);
            nextBoundary = [arr[1], arr[2]];
        }

        const startIdx = nextBoundary[0];
        const length = prefix[prefix.length - 1] - prefix[startIdx];
        const nodes = prefix.length - startIdx;

        if (length > maxLength) {
            maxLength = length;
            minNodes = nodes;
        } else if (length === maxLength) {
            minNodes = Math.min(minNodes, nodes);
        }

        for (const [v, w] of graph[u]) {
            if (v !== prev) {
                prefix.push(prefix[prefix.length - 1] + w);
                dfs(v, u, nextBoundary);
                prefix.pop();
            }
        }

        lastSeen.set(val, prevDepth);
    }

    dfs(0, -1, [0, 0]);
    return [maxLength, minNodes];
};
